import{_ as d,o as e,c as o,al as c}from"./chunks/framework.BawR2jEz.js";const u=JSON.parse('{"title":"Примеры regex для поиска","description":"Готовые регулярные выражения для типовых задач поиска и аудита в exDoc — имена, шаблоны, стили, скрипты, ссылки.","frontmatter":{"title":"Примеры regex для поиска","description":"Готовые регулярные выражения для типовых задач поиска и аудита в exDoc — имена, шаблоны, стили, скрипты, ссылки."},"headers":[],"relativePath":"search/regex-examples.md","filePath":"search/regex-examples.md"}'),r={name:"search/regex-examples.md"};function a(l,t,i,s,n,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<div><h1 id="примеры-regex-для-поиска" tabindex="-1">Примеры regex для поиска <a class="header-anchor" href="#примеры-regex-для-поиска" aria-label="Permalink to &quot;Примеры regex для поиска&quot;">​</a></h1><p>Готовые регулярные выражения для типовых задач. Включи опцию <strong>Регулярное выражение</strong> в строке поиска и вставь нужный паттерн. Все примеры рабочие и проверены на синтаксис.</p><h2 id="перед-стартом" tabindex="-1">Перед стартом <a class="header-anchor" href="#перед-стартом" aria-label="Permalink to &quot;Перед стартом&quot;">​</a></h2><ul><li>Без опции <strong>С учётом регистра</strong> поиск нечувствителен к регистру — <code>Block</code> находит «block», «BLOCK» и т.п. С опцией — точно как в паттерне.</li><li>Опция <strong>Целое слово</strong> автоматически отключается при включении <strong>Регулярного выражения</strong> — используй <code>\\b</code> в паттерне.</li><li>В режиме замены можно использовать обратные ссылки: <code>$1</code>, <code>$2</code>, <code>$3</code> для групп <code>(...)</code>.</li><li>При синтаксической ошибке в паттерне поле подсветится красной рамкой и появится сообщение.</li></ul><h2 id="имена-и-хэштеги" tabindex="-1">Имена и хэштеги <a class="header-anchor" href="#имена-и-хэштеги" aria-label="Permalink to &quot;Имена и хэштеги&quot;">​</a></h2><p>Применяется к областям «В названиях» и «В хэштегах».</p><table tabindex="0"><thead><tr><th>Задача</th><th>Паттерн</th><th>Пример совпадения</th></tr></thead><tbody><tr><td>Начинается на <code>block_</code></td><td><code>^block_</code></td><td><code>block_hero</code>, <code>block_footer</code></td></tr><tr><td>Заканчивается на <code>_form</code></td><td><code>_form$</code></td><td><code>contact_form</code>, <code>subscribe_form</code></td></tr><tr><td>Содержит цифры</td><td><code>\\d+</code></td><td><code>slider2</code>, <code>block_v3</code></td></tr><tr><td>Двойной дефис (опечатка)</td><td><code>--</code></td><td><code>my--block</code>, <code>header--main</code></td></tr><tr><td>Кириллица в имени</td><td><code>[а-яА-ЯёЁ]+</code></td><td>имена с русскими буквами</td></tr><tr><td><code>color</code> или <code>colour</code></td><td><code>colou?r</code></td><td><code>color_picker</code>, <code>text_colour</code></td></tr><tr><td>Один из вариантов</td><td><code>(slider|carousel|swiper)</code></td><td>любой из трёх в имени</td></tr><tr><td>Длинные имена (40+ символов)</td><td><code>^.{40,}$</code></td><td>сущности с подозрительно длинным именем</td></tr></tbody></table><h2 id="twig-html-—-шаблоны" tabindex="-1">TWIG / HTML — шаблоны <a class="header-anchor" href="#twig-html-—-шаблоны" aria-label="Permalink to &quot;TWIG / HTML — шаблоны&quot;">​</a></h2><p>Применяется к области «В TWIG-шаблонах».</p><table tabindex="0"><thead><tr><th>Задача</th><th>Паттерн</th><th>Что находит</th></tr></thead><tbody><tr><td><code>&lt;img&gt;</code> без атрибута <code>alt</code></td><td><code>&lt;img(?![^&gt;]*\\balt=)[^&gt;]*&gt;</code></td><td>картинки без alt-текста (a11y-аудит)</td></tr><tr><td>Inline-стили</td><td><code>style=&quot;[^&quot;]*&quot;</code></td><td>все <code>style=&quot;...&quot;</code> для рефакторинга в CSS</td></tr><tr><td>Bootstrap-кнопки</td><td><code>class=&quot;[^&quot;]*\\bbtn-</code></td><td>классы вида <code>btn-primary</code>, <code>btn-sm</code> и т.д.</td></tr><tr><td>Внешние ссылки без <code>rel=&quot;nofollow&quot;</code></td><td><code>&lt;a(?![^&gt;]*rel=&quot;[^&quot;]*nofollow)[^&gt;]*href=&quot;http</code></td><td>SEO-аудит</td></tr><tr><td>Простая TWIG-переменная</td><td><code>\\{\\{\\s*\\w+\\s*\\}\\}</code></td><td><code>{{ block_id }}</code>, <code>{{ title }}</code></td></tr><tr><td>TWIG-функция</td><td><code>\\{\\{\\s*\\w+\\(</code></td><td><code>{{ url(&#39;main&#39;) }}</code>, <code>{{ asset(...) }}</code></td></tr><tr><td>TWIG-фильтр</td><td><code>|\\s*\\w+</code></td><td><code>{{ price|number_format }}</code></td></tr><tr><td>Тег с data-атрибутом</td><td><code>&lt;\\w+[^&gt;]*\\bdata-block</code></td><td>разметка с кастомными data-block-*</td></tr><tr><td>HTML-комментарии</td><td><code>&lt;!--[\\s\\S]*?--&gt;</code></td><td>все блоки <code>&lt;!-- ... --&gt;</code></td></tr><tr><td>Жёстко прописанные URL</td><td><code>https?://[^\\s&quot;&#39;&lt;&gt;]+</code></td><td>абсолютные ссылки в коде</td></tr></tbody></table><h2 id="scss-css-—-стили" tabindex="-1">SCSS / CSS — стили <a class="header-anchor" href="#scss-css-—-стили" aria-label="Permalink to &quot;SCSS / CSS — стили&quot;">​</a></h2><p>Применяется к области «В SCSS-стилях».</p><table tabindex="0"><thead><tr><th>Задача</th><th>Паттерн</th><th>Что находит</th></tr></thead><tbody><tr><td>Использование <code>!important</code></td><td><code>!important</code></td><td>все правила с !important (для уборки)</td></tr><tr><td>Hex-цвет</td><td><code>#[0-9a-fA-F]{3,8}\\b</code></td><td><code>#fff</code>, <code>#ff5500</code>, <code>#ff5500aa</code></td></tr><tr><td><code>rgb</code> / <code>rgba</code></td><td><code>rgba?\\([^)]+\\)</code></td><td><code>rgb(255, 0, 0)</code>, <code>rgba(0,0,0,.5)</code></td></tr><tr><td>SCSS-переменная</td><td><code>\\$[\\w-]+</code></td><td><code>$primary</code>, <code>$bp-lg</code></td></tr><tr><td>Медиа-запрос</td><td><code>@media\\s*\\([^)]+\\)</code></td><td><code>@media (min-width: 768px)</code></td></tr><tr><td><code>position: fixed</code></td><td><code>position:\\s*fixed</code></td><td>подозрительные fixed-элементы</td></tr><tr><td>CSS-custom property</td><td><code>--[\\w-]+</code></td><td><code>--text-color</code>, <code>--spacing-lg</code></td></tr><tr><td>Большой z-index (1000+)</td><td><code>z-index:\\s*\\d{4,}</code></td><td><code>z-index: 9999</code> и подобное</td></tr><tr><td>Конкретный селектор</td><td><code>\\.btn-primary\\b</code></td><td>использования <code>.btn-primary</code></td></tr><tr><td>Anchor-positioning (новое)</td><td>`anchor-name</td><td>position-anchor`</td></tr></tbody></table><h2 id="js-—-скрипты" tabindex="-1">JS — скрипты <a class="header-anchor" href="#js-—-скрипты" aria-label="Permalink to &quot;JS — скрипты&quot;">​</a></h2><p>Применяется к области «В JS-скриптах».</p><table tabindex="0"><thead><tr><th>Задача</th><th>Паттерн</th><th>Что находит</th></tr></thead><tbody><tr><td>Отладочные <code>console.*</code></td><td><code>console\\.(log|warn|error|debug|info)</code></td><td>вызовы для уборки перед релизом</td></tr><tr><td>TODO / FIXME / HACK</td><td><code>\\b(TODO|FIXME|HACK|XXX)\\b</code></td><td>оставленные заметки в коде</td></tr><tr><td>ES6-импорты</td><td><code>^import\\s+</code></td><td><code>import { x } from &#39;...&#39;</code> (с флагом multiline)</td></tr><tr><td><code>var</code> (для миграции)</td><td><code>\\bvar\\s+\\w+</code></td><td>старые <code>var</code> объявления</td></tr><tr><td><code>setTimeout</code> с числом</td><td><code>setTimeout\\s*\\(\\s*[^,]+,\\s*\\d+\\)</code></td><td>таймеры с захардкоженной задержкой</td></tr><tr><td>Использование <code>eval</code></td><td><code>\\beval\\s*\\(</code></td><td>потенциально опасный код</td></tr><tr><td>Вызовы jQuery <code>$()</code></td><td><code>\\$\\(\\s*[&#39;&quot;]</code></td><td>проверить наличие jQuery-зависимостей</td></tr><tr><td><code>addEventListener</code></td><td><code>addEventListener\\s*\\(\\s*[&#39;&quot;][^&#39;&quot;]+[&#39;&quot;]</code></td><td>все подписки на события</td></tr><tr><td>async/await</td><td><code>\\b(async\\s+function|await\\s+)</code></td><td>async-код</td></tr></tbody></table><h2 id="ссылки-на-ресурсы" tabindex="-1">Ссылки на ресурсы <a class="header-anchor" href="#ссылки-на-ресурсы" aria-label="Permalink to &quot;Ссылки на ресурсы&quot;">​</a></h2><p>Применяется к областям «В ссылках на скрипты» и «В ссылках на стили».</p><table tabindex="0"><thead><tr><th>Задача</th><th>Паттерн</th><th>Что находит</th></tr></thead><tbody><tr><td>CDN-ссылки</td><td><code>cdn\\.|cdnjs\\.|jsdelivr|unpkg</code></td><td>внешние CDN-зависимости</td></tr><tr><td>HTTPS-только</td><td><code>^https://</code></td><td>проверка что нет http:// (mixed content)</td></tr><tr><td>Конкретный домен</td><td><code>googleapis\\.com</code></td><td>использование Google Fonts/Maps API</td></tr><tr><td>Локальные пути</td><td><code>^/[^/]</code></td><td>пути от корня (не <code>//</code> и не <code>http</code>)</td></tr><tr><td>Версионные параметры</td><td><code>\\?v=\\d</code></td><td>URL c версиями вида <code>?v=1.2.3</code></td></tr><tr><td>Минифицированные файлы</td><td><code>\\.min\\.(js|css)$</code></td><td>подключения <code>.min.js</code> / <code>.min.css</code></td></tr></tbody></table><h2 id="использование-с-заменои" tabindex="-1">Использование с заменой <a class="header-anchor" href="#использование-с-заменои" aria-label="Permalink to &quot;Использование с заменой&quot;">​</a></h2><p>Те же паттерны работают и в режиме замены. Обратные ссылки <code>$1</code>, <code>$2</code> в строке замены подставляют то, что попало в группы <code>(...)</code>.</p><table tabindex="0"><thead><tr><th>Задача</th><th>Найти</th><th>Заменить на</th><th>Результат</th></tr></thead><tbody><tr><td>Префикс старый → новый</td><td><code>^old-(\\w+)</code></td><td><code>new-$1</code></td><td><code>old-block</code> → <code>new-block</code></td></tr><tr><td>Местами поменять два слова</td><td><code>(\\w+)-(\\w+)</code></td><td><code>$2-$1</code></td><td><code>red-button</code> → <code>button-red</code></td></tr><tr><td>Удалить отладочные log</td><td><code>console\\.log\\([^)]*\\);?\\s*</code></td><td>(пусто)</td><td>строки убираются</td></tr><tr><td>Обновить версию</td><td><code>(\\?v=)\\d+\\.\\d+\\.\\d+</code></td><td><code>${1}2.0.0</code></td><td>все ссылки получают v=2.0.0</td></tr><tr><td>Переписать hex на var</td><td><code>#3b82f6\\b</code></td><td><code>var(--brand)</code></td><td>хардкод цвета → переменная</td></tr><tr><td>Дописать <code>rel=&quot;noopener&quot;</code></td><td><code>(&lt;a[^&gt;]*target=&quot;_blank&quot;(?![^&gt;]*rel=))</code></td><td><code>$1 rel=&quot;noopener&quot;</code></td><td>у целевых ссылок добавляется rel</td></tr></tbody></table><h2 id="полезно-знать" tabindex="-1">Полезно знать <a class="header-anchor" href="#полезно-знать" aria-label="Permalink to &quot;Полезно знать&quot;">​</a></h2><ul><li>Точка <code>.</code> совпадает с любым символом, кроме перевода строки. Чтобы и с переводом — используй <code>[\\s\\S]</code>.</li><li><code>\\s</code> — любой пробельный (включая табы и переводы строки), <code>\\S</code> — наоборот.</li><li><code>\\w</code> — буква/цифра/<code>_</code>, <code>\\W</code> — наоборот.</li><li><code>\\b</code> — граница слова (между <code>\\w</code> и <code>\\W</code>).</li><li><code>(?:...)</code> — группа без захвата (не создаёт <code>$1</code>).</li><li><code>(?!...)</code> — негативный lookahead: «дальше НЕ должно быть».</li><li><code>*?</code>, <code>+?</code> — нежадные квантификаторы (минимум совпадение вместо максимума).</li><li>В наших паттернах нельзя использовать модификатор <code>e</code> (eval) — он отключён в целях безопасности.</li></ul><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./">Поиск</a> — обычный поиск с опциями</li><li><a href="./replace.html">Замена</a> — массовая замена с превью</li></ul></div>',1)])])}const p=d(r,[["render",a]]);export{u as __pageData,p as default};
